let lang = navigator.language.startsWith('es') ? 'es' : 'en';
let state = {profile:clone(DEFAULT_PROFILE), completed:[], created:false, remember:false, sample:false};
let view = 'home', wizardStep = 1, draft = null, filter = 'next', drill = -1, answers = [], offlineReady = false, offlineSettled = false, registration = null, installPrompt = null;
let toastTimer, printPending = false, planStore = null, samplePrevious = null, creatingNew = false, openDetails = new Set();
try {
  planStore = createPlanStore(localStorage);
  lang = localStorage.getItem('nr-language') === 'es' ? 'es' : localStorage.getItem('nr-language') === 'en' ? 'en' : lang;
  const raw = planStore.load();
  if (raw) { const restored = validateImport(JSON.parse(raw)); state = {...state,...restored,created:true,remember:true}; }
} catch { /* A corrupt or unavailable saved copy never stops the app. */ }
const t = key => copy[lang][key] || copy.en[key] || key;
const demoProfile = () => normalizeProfile({...DEFAULT_PROFILE,people:3,needs:['transport','mobility','pets','power'],hazards:['outage','flood'],budget:'free'});
const L = value => typeof value === 'string' ? value : value?.[lang] || value?.en || '';
const labelList = (list, ids) => list.filter(x=>ids.includes(x.id)).map(x=>L(x.label)).join(', ');
const button = (text, act, type='primary', extra='') => `<button class="button ${type === 'secondary' ? 'secondary' : type === 'white' ? 'white' : ''}" data-act="${act}" ${extra}>${text}${icon('arrow')}</button>`;
const offlineText = () => t(offlineReady ? navigator.onLine ? 'offlineReady' : 'offlineActive' : offlineSettled ? 'offlineUnavailable' : 'offlinePending');
function toast(message) { const el=$('#toast'); el.textContent=message; el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4500); }
function persist({forget=false}={}) {
  if (state.sample) return true;
  if (!state.remember || !state.created) { if(!forget)return true;try { const result=planStore?.forget();if(result?.conflict){toast(lang==='es'?'Otra pestaña guardó un plan diferente. Se conservó esa copia.':'Another tab saved a different plan. That saved copy was kept.');return false;} return true; } catch { toast(lang==='es'?'No se pudo eliminar la copia guardada. Revisa el almacenamiento del navegador.':'Could not remove the saved copy. Check this browser’s storage settings.'); return false; } }
  try { if(!planStore)throw new Error('Storage unavailable');planStore.save({schemaVersion:1,profile:state.profile,completed:state.completed,exportedAt:new Date().toISOString()}); return true; }
  catch(error) { state.remember=false; toast(error instanceof StorageConflictError?lang==='es'?'Otra pestaña cambió el plan guardado. Exporta este plan para conservarlo.':'Another tab changed the saved plan. Export this plan to keep it.':t('saveFailed')); return false; }
}
function navigate(target) {
  if(target === 'household') { creatingNew=false; draft=clone(state.profile); wizardStep=1; }
  view=target; drill=-1;
  const targetUrl=new URL(location.href);targetUrl.searchParams.delete('modal');targetUrl.hash=target;history.replaceState(null,'',targetUrl.pathname+targetUrl.search+targetUrl.hash);
  render(); $('#main')?.focus({preventScroll:true}); window.scrollTo({top:0,behavior:'instant'});
}
function art() {
  return `<div class="hero-art" aria-label="${E(t('heroBody'))}"><div class="orbit"><div class="orbit-center">${icon('home')}<span>${t('you')}</span><small>${t('orbitSub')}</small></div><span class="orbit-label one">${icon('people')}${t('people')}</span><span class="orbit-label two">${icon('heart')}${t('support')}</span><span class="orbit-label three">${icon('plan')}${t('yourPlan')}</span></div><span class="art-caption">${t('artCaption')}</span></div>`;
}
function sampleBanner() { return state.sample ? `<div class="sample-banner"><span>${t('sampleLabel')}</span><button class="text-button" data-act="new">${t('leaveSample')}</button></div>` : ''; }
function intro() {
  return `<div class="hero"><div class="hero-copy"><div class="kicker eyebrow"><span class="line"></span>${t('kicker')}</div><h1>${t('hero')}</h1><p>${t('heroBody')}</p><div class="hero-buttons">${button(t('build'),'build')}<button class="text-button" data-act="sample">${t('sample')}${icon('arrow')}</button></div></div>${art()}</div><div class="section-head"><h2>${t('begin')}</h2><span>${t('beginHint')}</span></div><div class="start-grid"><section class="panel"><div class="step-list">${[1,2,3].map(i=>`<div class="step"><span class="step-num mono">0${i}</span><div><h3>${t(`step${i}`)}</h3><p>${t(`step${i}body`)}</p></div></div>`).join('')}</div></section><section class="panel callout"><div class="large-icon">${icon('link')}</div><h2>${t('calloutTitle')}</h2><p>${t('calloutBody')}</p><button class="text-button" data-act="build">${t('calloutAction')}${icon('arrow')}</button></section></div>`;
}
function overview() {
  if(!state.created) return intro()+quietStrip();
  const p=getPlanState(state.profile,state.completed), next=p.readyTasks[0]||p.pendingTasks[0];
  const base=generatePlan({...state.profile,needs:[]}), extra=p.total-base.length;
  return sampleBanner()+`<div class="page-heading"><div><div class="kicker eyebrow"><span class="line"></span>${t('kicker')}</div><h1>${t('readyPlan')}</h1><p>${t('heroBody')}</p></div><button class="text-button" data-act="build">${t('edit')}${icon('settings')}</button></div><div class="summary-grid"><section class="panel next-card"><span class="eyebrow">${t('first')}</span><h2>${next?E(L(next.title)):t('practiceFinished')}</h2><p>${next?E(L(next.why)):t('practiceGoalBody')}</p><div class="card-bottom">${button(t(next?'openPlan':'startPractice'),next?'plan':'practice','white')}<span class="mono">${next?`${next.minutes} ${t('minutes')} · ${t(next.cost==='free'?'noCost':'supplies')}`:''}</span></div></section><section class="panel progress-panel"><h3>${t('progress')}</h3><div class="fraction">${p.done}<span> / ${p.total}</span></div><span class="muted">${t('completed')}</span><progress class="meter" value="${p.done}" max="${p.total}" aria-label="${E(t('completed'))}"></progress><p class="muted"><small>${t('notScore')}</small></p></section></div><div class="start-grid"><section class="panel"><h3>${t('coverage')}</h3><ul class="coverage-list"><li><span>${t('peopleCount')}</span><span>${state.profile.people}</span></li><li><span>${t('days')}</span><span>${state.profile.days} ${t('daysOption')}</span></li></ul><div class="chips">${state.profile.hazards.map(id=>`<span class="chip">${E(labelList(HAZARDS,[id]))}</span>`).join('')}${state.profile.needs.map(id=>`<span class="chip">${E(labelList(NEEDS,[id]))}</span>`).join('')}</div><button class="text-button" data-act="compare">${t('compare')}${icon('arrow')}</button><p class="muted"><small>${extra>0?`${extra} ${t('stepsAdded')}`:t('noExtra')}</small></p></section><section class="panel callout"><div class="large-icon">${icon('practice')}</div><h2>${t('practiceGoal')}</h2><p>${t('practiceGoalBody')}</p><button class="text-button" data-act="practice">${t('startPractice')}${icon('arrow')}</button></section></div>${quietStrip()}`;
}
function quietStrip() {return `<div class="quiet-strip"><span>${icon('lock')}${t('noAccount')}</span><span>${icon('shield')}${t('localOnly')}</span><span data-offline>${icon('wifi')}<span>${offlineText()}</span></span></div>`;}
function choice(item,group) {return `<label class="choice"><input type="checkbox" name="${group}" value="${E(item.id)}" ${draft[group].includes(item.id)?'checked':''}><span><b>${E(L(item.label))}</b><small>${E(L(item.summary))}</small></span></label>`;}
function field(name, label, help, multiline=false) { return `<div class="field"><label for="f-${name}">${t(label)}</label>${multiline?`<textarea id="f-${name}" name="${name}" aria-describedby="help-${name}" maxlength="400">${E(draft[name])}</textarea>`:`<input id="f-${name}" name="${name}" aria-describedby="help-${name}" maxlength="200" autocomplete="off" value="${E(draft[name])}">`}<small id="help-${name}">${t(help)}</small></div>`; }
function household() {
  draft ||= clone(state.profile);
  let body='';
  if(wizardStep===1) body=`<h2>${t('houseTitle')}</h2><p>${t('houseIntro')}</p><div class="fields-row"><div class="field"><label for="f-people">${t('peopleCount')}</label><input id="f-people" type="number" min="1" max="12" step="1" name="people" required value="${E(draft.people)}"></div><div class="field"><label for="f-days">${t('days')}</label><input id="f-days" type="number" min="3" max="14" step="1" name="days" required value="${E(draft.days)}"><small>${t('daysHelp')}</small></div></div><fieldset><legend>${t('hazards')}</legend><div class="choice-grid">${HAZARDS.map(x=>choice(x,'hazards')).join('')}</div><p class="notice">${t('hazardHelp')}</p></fieldset>`;
  if(wizardStep===2) body=`<h2>${t('needsTitle')}</h2><p>${t('needsIntro')}</p><fieldset><legend>${t('needsLegend')}</legend><div class="choice-grid">${NEEDS.map(x=>choice(x,'needs')).join('')}</div></fieldset><fieldset><legend>${t('budgetLegend')}</legend><div class="choice-grid"><label class="choice"><input type="radio" name="budget" value="all" ${draft.budget==='all'?'checked':''}><span><b>${t('budgetAll')}</b><small>${t('budgetHelp')}</small></span></label><label class="choice"><input type="radio" name="budget" value="free" ${draft.budget==='free'?'checked':''}><span><b>${t('budgetFree')}</b><small>${t('budgetHelp')}</small></span></label></div></fieldset>`;
  if(wizardStep===3) body=`<h2>${t('handoffTitle')}</h2><p>${t('handoffIntro')}</p><div class="fields-row">${field('meeting','meeting','meetingHelp')}${field('outside','outside','outsideHelp')}</div>${field('contact','contact','contactHelp')}${field('transport','transport','transportHelp')}${field('notes','notes','notesHelp',true)}<label class="privacy-choice"><input type="checkbox" name="remember" ${draft.remember??state.remember?'checked':''}><span>${t('remember')}<small>${t('rememberHelp')}</small></span></label>`;
  return `<div class="wizard"><div class="wizard-progress">${[1,2,3].map(i=>`<div class="${i===wizardStep?'current':i<wizardStep?'complete':''}" ${i===wizardStep?'aria-current="step"':''}>0${i} · ${t(i===1?'people':i===2?'needs':'yourPlan')}</div>`).join('')}</div><form id="household-form" class="wizard-panel" novalidate>${body}<p id="form-error" class="error" role="alert"></p><div class="wizard-bottom"><button type="button" class="text-button" data-act="${wizardStep===1?'home':'back'}">${t(wizardStep===1?'cancel':'back')}</button><button type="submit" class="button">${t(wizardStep===3?state.created&&!state.sample?'saveChanges':'create':'nextButton')}${icon('arrow')}</button></div></form></div>`;
}
function emptyPlan() { return `<div class="empty">${icon('plan')}<h3>${t('noPlan')}</h3><p>${t('noPlanBody')}</p>${button(t('build'),'build')}</div>`; }
function taskCard(task) {
  const completed=state.completed.includes(task.id), all=generatePlan(state.profile), blockers=(task.requires||[]).filter(id=>!state.completed.includes(id));
  const source=SOURCES[task.sourceId];
  return `<article class="task ${completed?'completed':''}"><input class="task-check" type="checkbox" id="task-${E(task.id)}" data-task="${E(task.id)}" ${completed?'checked':''} aria-label="${E(L(task.title))}"><div><div class="task-meta"><span class="tag">${t(task.cost==='free'?'noCost':'supplies')}</span><span>${task.minutes} ${t('minutes')}</span></div><label class="task-title" for="task-${E(task.id)}">${E(L(task.title))}</label><p>${E(L(task.body))}</p>${blockers.length?`<p class="dependency">${t('before')} ${blockers.map(id=>E(L(all.find(x=>x.id===id)?.title)||id)).join(' · ')}</p>`:''}<details data-detail="${E(task.id)}" ${openDetails.has(task.id)?'open':''}><summary>${t('why')}</summary><p>${E(L(task.why))}</p>${source?`<a href="${E(source.url)}" target="_blank" rel="noopener noreferrer">${t('learn')} · ${E(source.title)} ${icon('external')}</a>`:''}</details></div></article>`;
}
function plan() {
  if(!state.created)return emptyPlan();
  const p=getPlanState(state.profile,state.completed), water=waterTarget(state.profile);
  const tasks=filter==='done'?p.completedTasks:filter==='next'?p.readyTasks:filter==='free'?p.pendingTasks.filter(x=>x.cost==='free'):p.tasks;
  return sampleBanner()+`<div class="page-heading"><div><h1>${t('readyPlan')}</h1><p>${t('planIntro')}</p></div><button class="text-button" data-act="build">${t('edit')}${icon('settings')}</button></div><div class="toolbar"><div class="segmented" role="group" aria-label="${E(t('plan'))}">${['next','all','free','done'].map(x=>`<button class="${filter===x?'active':''}" data-filter="${x}" aria-pressed="${filter===x}">${t(x)}</button>`).join('')}</div><button class="button secondary" data-act="print">${icon('print')}${t('print')}</button></div><div class="plan-layout"><div class="tasks">${tasks.length?tasks.map(taskCard).join(''):`<div class="empty">${icon('check')}<h3>${t('nothing')}</h3><p>${t('nothingBody')}</p><button class="text-button" data-filter="all">${t('all')}${icon('arrow')}</button></div>`}</div><aside class="plan-aside"><section class="panel progress-panel"><h3>${t('progress')}</h3><div class="fraction">${p.done}<span> / ${p.total}</span></div><p>${t('completed')}</p><progress class="meter" value="${p.done}" max="${p.total}" aria-label="${E(t('completed'))}"></progress><p>${t('notScore')}</p></section><section class="panel"><h3>${t('water')}</h3><div class="water-number">${water.gallons} <span>${t('gallons')}</span></div><span class="mono">${Number(water.liters).toFixed(1)} ${t('liters')} · ${state.profile.people} × ${state.profile.days}</span><p>${t('waterNote')}</p></section><section class="panel"><h3>${t('howOrder')}</h3><p>${t('orderBody')}</p><p>${t('timeHelp')}</p><button class="text-button" data-act="export">${icon('download')}${t('export')}</button><button class="text-button" data-act="import">${t('import')}</button></section></aside></div>`;
}
function practice() {
  if(drill===-1)return `<div class="page-heading"><div><h1>${t('practiceTitle')}</h1><p>${t('practiceIntro')}</p></div></div><div class="practice-grid"><section class="scenario-card"><span class="eyebrow">${t('scenarioTag')}</span><h2>${t('scenarioTitle')}</h2><p>${t('scenarioBody')}</p>${button(t('startPractice'),'drill-start','white')}<div class="practice-note">${t('practiceSmall')}</div></section><section class="panel"><div class="large-icon">${icon('people')}</div><h2>${t('practiceGoal')}</h2><p class="notice">${t('practiceGoalBody')}</p><p class="muted">${t('practiceNoScore')}</p>${state.created?`<button class="text-button" data-act="print">${t('print')}${icon('print')}</button>`:''}</section></div>`;
  if(drill===3)return `<div class="drill-page panel"><span class="eyebrow">${t('scenarioTag')}</span><h2>${t('practiceFinished')}</h2><p>${t('reviewIntro')}</p><ul class="drill-review">${['reviewOne','reviewTwo','reviewThree'].map(x=>`<li>${t(x)}</li>`).join('')}</ul><p class="notice">${t('practiceComplete')}</p><div class="hero-buttons">${button(t(state.created?'openPlan':'build'),state.created?'plan':'build')}<button class="text-button" data-act="drill-start">${t('repeat')}</button></div></div>`;
  const n=drill+1, answer=answers[drill];
  return `<section class="drill-page panel"><div class="drill-progress"><span>${t('scenarioTag')}</span><span>${n} / 3</span></div><h2>${t(`question${n}`)}</h2><p>${t('practiceNoScore')}</p><div class="answers">${['a','b'].map((a,i)=>`<button class="answer ${answer===i?'selected':''}" data-answer="${i}" aria-pressed="${answer===i}">${t(`q${n}${a}`)}${icon(answer===i?'check':'arrow')}</button>`).join('')}</div>${answer!==undefined?`<div class="drill-feedback"><b>${t(answer===0?'usefulChoice':'gapChoice')}</b><p>${t(`q${n}why`)}</p></div><div class="hero-buttons">${button(t(n===3?'finishPractice':'reviewNext'),'drill-next')}</div>`:''}<div class="practice-note muted">${t('practiceSmall')}</div></section>`;
}
function guide() {
  return `<div class="page-heading"><div><h1>${t('guideTitle')}</h1><p>${t('guideIntro')}</p></div></div><div class="resource-bar"><div><h3>${t('scopeTitle')}</h3><p>${t('scopeBody')}</p></div><button class="button secondary" data-act="official">${t('official')}${icon('external')}</button></div><div class="sources-grid">${Object.entries(SOURCES).map(([id,s],i)=>`<article class="panel source-card"><span class="eyebrow">SOURCE / ${String(i+1).padStart(2,'0')}</span><h3>${E(s.title)}</h3><p>${E(L(s.summary))}</p><a href="${E(s.url)}" target="_blank" rel="noopener noreferrer">${t('learn')}${icon('external')}</a><small class="reviewed">${t('reviewed')}</small></article>`).join('')}</div><p class="notice">${t('scopeNote')}</p>`;
}
function render() {
  document.documentElement.lang=lang;document.title=`NeighborReady — ${t('yourPlan')}`;
  $('.skip-link').textContent=lang==='es'?'Saltar al contenido':'Skip to content';
  const nav=['home','household','plan','practice','guide'];
  const body={home:overview,household,plan,practice,guide}[view]();
  $('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#home" data-act="home"><img src="./icon.svg" alt=""><span>NeighborReady</span></a><span class="nav-label">${t('yourSpace')}</span><nav class="nav" aria-label="${E(t('yourSpace'))}">${nav.map(x=>`<button data-act="${x}" class="${view===x?'active':''}" ${view===x?'aria-current="page"':''} aria-label="${E(t(x))}">${icon(x==='household'?'people':x==='guide'?'book':x)}<span>${t(x)}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-mark">${icon('link')}</div><h3>${t('sideTitle')}</h3><p>${t('sideBody')}</p><button data-act="settings">${t('privacy')}</button></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><span class="mono">${String(nav.indexOf(view)+1).padStart(2,'0')}</span><span>/</span><b>${t(view)}</b></div><div class="header-actions"><button class="quiet-button" data-act="settings" aria-label="${E(t('privacy'))}">${icon('lock')}<span class="privacy-label">${t(state.remember?'saved':'session')}</span></button><button class="language" data-act="language" lang="${lang==='en'?'es':'en'}">${lang==='en'?'Español':'English'}</button></div></header><main id="main" class="main fade-in" tabindex="-1">${body}<footer class="footer"><span>${t('footer')}</span><button class="quiet-button" data-act="guide">${t('sources')}${icon('external')}</button></footer></main></div>`;
  if(view==='home'&&!state.created){const recover=document.createElement('button');recover.className='text-button';recover.dataset.act='import';recover.textContent=t('import');$('.hero-buttons')?.append(recover);}
}
function dialog(title,body,actions='') {
  const el=$('#modal');el.classList.remove('print-preview');el.innerHTML=`<h2 id="modal-title" tabindex="-1">${title}</h2>${body}<div class="modal-actions">${actions}<button class="button secondary" data-act="close">${t('close')}</button></div>`; if(!el.open)el.showModal();$('#modal-title').focus({preventScroll:true});el.scrollTop=0;
}
function settings() {
  dialog(t('privacyTitle'),`<p>${t('privacyBody')}</p><label class="settings-line"><span>${t('shared')}<small class="muted">${t('sharedHelp')}</small></span><input id="remember-toggle" type="checkbox" ${state.remember?'checked':''} ${!state.created||state.sample?'disabled':''}></label><div class="settings-line"><span>${t('settingsOffline')}</span><b data-offline-label>${offlineText()}</b></div><p>${t('settingsOfflineHelp')}</p><p>${t('installHelp')}</p>${state.created?`<p>${t('exportNote')}</p><div class="hero-buttons"><button class="button secondary" data-act="export">${icon('download')}${t('export')}</button><button class="text-button" data-act="import">${t('import')}</button></div>`:''}${registration?.waiting?`<p class="notice">${t('updateAvailable')}</p><button class="button" data-act="update">${t('update')}</button>`:''}`,`${installPrompt?`<button class="button" data-act="install">${t('install')}</button>`:''}${state.created?`<button class="button secondary danger" data-act="clear">${t('clear')}</button>`:''}`);
  if(!state.created){const recover=document.createElement('button');recover.className='button secondary';recover.dataset.act='import';recover.textContent=t('import');$('.modal-actions',$('#modal')).prepend(recover);}
}
function compare() {
  const base=generatePlan({...state.profile,needs:[]}), current=generatePlan(state.profile), baseIds=new Set(base.map(x=>x.id)), added=current.filter(x=>!baseIds.has(x.id));
  dialog(t('customTitle'),`<p>${t('customBody')}</p><ul class="coverage-list"><li><span>${t('baseline')}</span><b>${base.length}</b></li><li><span>${t('adapted')}</span><b>${current.length}</b></li></ul><h3 class="compare-subtitle">${t('extra')}</h3>${added.length?`<ul class="drill-review">${added.map(x=>`<li>${E(L(x.title))}<small class="muted"> — ${E(L(x.why))}</small></li>`).join('')}</ul>`:`<p>${t('noExtra')}</p>`}`);
}
function exportPlan() {
  if(!state.created)return;
  const blob=new Blob([JSON.stringify({schemaVersion:1,profile:state.profile,completed:state.completed,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});
  const url=URL.createObjectURL(blob), a=document.createElement('a');a.href=url;a.download='neighbor-ready-plan.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('downloaded'));
}
function createPrintDocument() {
  if(!state.created)return;
  $('.print-only')?.remove();const el=document.createElement('div');el.className='print-only print-page';
  const rows=['meeting','outside','contact','transport','notes'];
  const tasks=generatePlan(state.profile),water=waterTarget(state.profile);
  el.innerHTML=`<h1>NeighborReady</h1><p>${t('printed')} · ${state.sample?t('sampleLabel'):t('you')}</p><p>${t('paperDate')}: ${new Date().toLocaleDateString(lang==='es'?'es-US':'en-US')}</p><div class="wallet"><h2>${t('wallet')}</h2><table class="print-table">${rows.map(x=>`<tr><td>${t(x)}</td><td>${E(state.profile[x])||t('notFilled')} ${!state.profile[x]?'________________________________':''}</td></tr>`).join('')}</table><p>${t('paperSafety')}</p></div><p><b>${t('peopleCount')}:</b> ${state.profile.people} · <b>${t('days')}:</b> ${state.profile.days}</p><p><b>${t('hazards')}:</b> ${E(labelList(HAZARDS,state.profile.hazards))}</p><p><b>${t('paperNeeds')}:</b> ${E(labelList(NEEDS,state.profile.needs))||'—'}</p><p><b>${t('water')}:</b> ${water.gallons} ${t('gallons')} / ${Number(water.liters).toFixed(1)} ${t('liters')}. ${t('waterNote')}</p><h2>${t('paperChecklist')}</h2><ul class="print-checklist">${tasks.map(x=>`<li>${state.completed.includes(x.id)?'[✓]':'[ ]'} <b>${E(L(x.title))}</b> — ${E(L(x.body))}</li>`).join('')}</ul><div class="print-source">${t('reviewed')} · ${t('scopeNote')}<p>${Object.values(SOURCES).map(s=>E(s.url)).join('<br>')}</p></div>`;
  document.body.append(el);return el;
}
function printPlan() {const el=createPrintDocument();if(!el)return;dialog(t('print'),`<p>${t('exportNote')}</p><div class="paper-preview">${el.innerHTML}</div>`,`<button class="button" data-act="print-confirm">${icon('print')}${t('print')}</button>`);$('#modal').classList.add('print-preview');}
function startOwn() { creatingNew=true;history.replaceState(null,'',location.pathname+'#household');$('#modal').close();draft=clone(DEFAULT_PROFILE);draft.remember=false;wizardStep=1;view='household';render();$('#main').focus();window.scrollTo(0,0);}
function collectDraft() {
  const form=$('#household-form');if(!form)return;
  const data=new FormData(form);
  if(wizardStep===1) {draft.people=Number(data.get('people'));draft.days=Number(data.get('days'));draft.hazards=data.getAll('hazards');}
  if(wizardStep===2) {draft.needs=data.getAll('needs');draft.budget=data.get('budget');}
  if(wizardStep===3) {for(const key of ['meeting','outside','contact','transport','notes'])draft[key]=String(data.get(key)||'');draft.remember=data.has('remember');}
}
document.addEventListener('submit',event=>{
  if(event.target.id!=='household-form')return;event.preventDefault();collectDraft();
  if(wizardStep===1){if(!Number.isInteger(draft.people)||draft.people<1||draft.people>12||!Number.isInteger(draft.days)||draft.days<3||draft.days>14){$('#form-error').textContent=t('peopleError');$('#f-people').focus();return;}if(!draft.hazards.length){$('#form-error').textContent=t('hazardError');return;}}
  if(wizardStep<3){wizardStep++;render();$('#main').focus();window.scrollTo(0,0);return;}
  const updated=state.created&&!state.sample&&!creatingNew; const previousProfile=state.profile; const previouslyRemembered=state.remember; if(!updated)state.completed=[]; samplePrevious=null; state.profile=normalizeProfile(draft);state.remember=Boolean(draft.remember);state.created=true;state.sample=false;history.replaceState(null,'',location.pathname+'#home');
  const generated=generatePlan(state.profile); const valid=new Set(generated.filter(x=>!(updated&&(previousProfile.people!==state.profile.people||previousProfile.days!==state.profile.days)&&x.cost==='supplies')).map(x=>x.id));state.completed=state.completed.filter(id=>valid.has(id));const savedOk=persist({forget:previouslyRemembered&&!state.remember});navigate('home');if(savedOk)toast(t(updated?'planUpdated':'planCreated'));
});
document.addEventListener('input',event=>{if(event.target.closest('#household-form'))collectDraft();});
document.addEventListener('change',event=>{
  if(event.target.closest('#household-form'))collectDraft();
  if(event.target.id==='remember-toggle'){state.remember=event.target.checked;const savedOk=persist({forget:!state.remember});$('#modal').close();render();if(savedOk)toast(t(state.remember?'savedToast':'sessionToast'));}
  if(event.target.dataset.task){const id=event.target.dataset.task,task=generatePlan(state.profile).find(x=>x.id===id);if(!task)return;const checked=event.target.checked;state.completed=checked?[...new Set([...state.completed,id])]:state.completed.filter(x=>x!==id);const savedOk=persist();render();const next=$(`#task-${id}`);if(next)next.focus({preventScroll:true});else $('#main').focus({preventScroll:true});if(savedOk)toast(t(checked?'marked':'unmarked')+(checked&&task.requires.some(x=>!state.completed.includes(x))?' '+t('pendingRelated'):''));}
});
document.addEventListener('toggle',event=>{const id=event.target.dataset?.detail;if(id){if(event.target.open)openDetails.add(id);else openDetails.delete(id);}},true);
document.addEventListener('click',async event=>{
  const el=event.target.closest('[data-act],[data-filter],[data-answer]');if(!el)return;
  if(el.dataset.filter){filter=el.dataset.filter;render();$(`[data-filter="${filter}"]`)?.focus({preventScroll:true});return;}
  if(el.dataset.answer!==undefined){const selected=Number(el.dataset.answer);answers[drill]=selected;render();$(`[data-answer="${selected}"]`)?.focus({preventScroll:true});$('.drill-feedback')?.setAttribute('role','status');return;}
  const action=el.dataset.act;
  if(['home','plan','practice','guide'].includes(action)){event.preventDefault();$('#modal').close();navigate(action);return;}
  if(action==='build'||action==='household'){navigate('household');return;}
  if(action==='new'){startOwn();return;}
  if(action==='sample'){ if(!state.sample)samplePrevious=clone(state); state={profile:demoProfile(),completed:[],created:true,remember:false,sample:true};history.replaceState(null,'',location.pathname+'?sample=1#home');navigate('home');return;}
  if(action==='back'){collectDraft();wizardStep=Math.max(1,wizardStep-1);render();$('#main').focus();return;}
  if(action==='language'){collectDraft();lang=lang==='en'?'es':'en';try{localStorage.setItem('nr-language',lang);}catch{}const localeUrl=new URL(location.href);if(localeUrl.searchParams.has('lang')){localeUrl.searchParams.set('lang',lang);history.replaceState(null,'',localeUrl.pathname+localeUrl.search+localeUrl.hash);}$('#toast').classList.remove('visible');$('#modal').close();render();$('[data-act="language"]')?.focus({preventScroll:true});return;}
  if(action==='settings'){settings();return;}
  if(action==='close'){$('#modal').close();return;}
  if(action==='compare'){compare();return;}
  if(action==='print'){printPlan();return;}
  if(action==='print-confirm'){printPending=true;$('#modal').close();window.print();return;}
  if(action==='export'){exportPlan();return;}
  if(action==='import'){
    dialog(t('import'),`<p>${t('importNote')}</p><input type="file" id="import-file" accept=".json,application/json" aria-label="${E(t('import'))}"><p id="import-error" class="error" role="alert"></p>`);
    $('#import-file').addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>131072)throw new Error(lang==='es'?'El archivo es demasiado grande.':'The backup is too large.');const imported=validateImport(JSON.parse(await file.text()));state={...state,...imported,created:true,sample:false};samplePrevious=null;history.replaceState(null,'',location.pathname+'#home');const savedOk=persist();$('#modal').close();navigate('home');if(savedOk)toast(t('imported'));}catch(error){$('#import-error').textContent=lang==='es'?'No se pudo importar. Elige una copia JSON válida de NeighborReady.':`Could not import: ${error.message}`;}});return;
  }
  if(action==='clear'){ if(state.sample){ state=samplePrevious||{profile:clone(DEFAULT_PROFILE),completed:[],created:false,remember:false,sample:false}; samplePrevious=null;history.replaceState(null,'',location.pathname+'#home'); $('#modal').close();navigate('home');return;} dialog(t('clearTitle'),`<p>${t('clearBody')}</p>`,`<button class="button danger" data-act="delete">${t('delete')}</button>`);return;}
  if(action==='delete'){state={profile:clone(DEFAULT_PROFILE),completed:[],created:false,remember:false,sample:false};const cleared=persist({forget:true});draft=null;samplePrevious=null;$('.print-only')?.remove();$('#modal').close();navigate('home');if(cleared)toast(t('deleted'));return;}
  if(action==='drill-start'){drill=0;answers=[];view='practice';render();$('#main').focus();return;}
  if(action==='drill-next'){drill++;render();$('#main').focus();return;}
  if(action==='official'){dialog(t('official'),`<p>${t('scopeBody')}</p><p><a href="https://www.weather.gov/alerts" target="_blank" rel="noopener noreferrer">National Weather Service — alerts ${icon('external')}</a></p><p><a href="https://www.redcross.org/get-help/disaster-relief-and-recovery-services/find-an-open-shelter.html" target="_blank" rel="noopener noreferrer">American Red Cross — open shelters ${icon('external')}</a></p><p><a href="https://www.fema.gov/locations" target="_blank" rel="noopener noreferrer">FEMA — regions and local resources ${icon('external')}</a></p><p>${t('scopeNote')}</p>`);return;}
  if(action==='install'&&installPrompt){await installPrompt.prompt();installPrompt=null;settings();return;}
  if(action==='update'&&registration?.waiting){registration.waiting.postMessage({type:'SKIP_WAITING'});return;}
});
window.addEventListener('hashchange',()=>{const target=location.hash.slice(1);if(['home','household','plan','practice','guide'].includes(target))navigate(target);});
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});
window.addEventListener('storage',event=>{if(event.key==='nr-plan-v1'&&state.created&&state.remember&&!state.sample){collectDraft();state.remember=false;render();toast(lang==='es'?'Otra pestaña cambió la copia guardada. Este plan sigue en tu sesión.':'Another tab changed the saved copy. This plan remains in your session.');}});
window.addEventListener('beforeprint',()=>{if(state.created&&!$('.print-only'))createPrintDocument();});
window.addEventListener('afterprint',()=>{printPending=false;$('.print-only')?.remove();});
$('#modal').addEventListener('close',()=>{if($('#modal').classList.contains('print-preview')&&!printPending)$('.print-only')?.remove();const current=new URL(location.href);if(current.searchParams.has('modal')){current.searchParams.delete('modal');history.replaceState(null,'',current.pathname+current.search+current.hash);}});
window.addEventListener('beforeunload',event=>{if(state.created&&!state.remember&&!state.sample){event.preventDefault();event.returnValue='';}});
function refreshOfflineLabels(){document.querySelectorAll('[data-offline]').forEach(el=>{el.innerHTML=`${icon('wifi')}<span>${offlineText()}</span>`;});document.querySelectorAll('[data-offline-label]').forEach(el=>el.textContent=offlineText());}
async function verifyOffline(){
  if(!navigator.serviceWorker?.controller){offlineReady=false;refreshOfflineLabels();return;}
  const channel=new MessageChannel();const timeout=setTimeout(()=>{offlineReady=false;offlineSettled=true;refreshOfflineLabels();},4000);
  channel.port1.onmessage=event=>{if(event.data?.type==='OFFLINE_STATUS'){clearTimeout(timeout);offlineReady=Boolean(event.data.ready);offlineSettled=true;refreshOfflineLabels();channel.port1.close();}};
  navigator.serviceWorker.controller.postMessage({type:'VERIFY_OFFLINE'},[channel.port2]);
}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')verifyOffline();});
window.addEventListener('online',()=>{verifyOffline();refreshOfflineLabels();});window.addEventListener('offline',refreshOfflineLabels);
let reloadingForUpdate=false;
if('serviceWorker' in navigator){
  navigator.serviceWorker.register('./sw.js').then(async reg=>{registration=reg;await navigator.serviceWorker.ready;verifyOffline();reg.addEventListener('updatefound',()=>{reg.installing?.addEventListener('statechange',()=>{if(reg.waiting&&navigator.serviceWorker.controller)toast(t('updateAvailable'));});});}).catch(()=>{offlineReady=false;offlineSettled=true;refreshOfflineLabels();});
  navigator.serviceWorker.addEventListener('controllerchange',()=>{if(reloadingForUpdate){location.reload();return;}verifyOffline();});
}else{offlineSettled=true;}
document.addEventListener('click',event=>{if(event.target.closest('[data-act="update"]'))reloadingForUpdate=true;});
const demoParams=new URLSearchParams(location.search);
if(demoParams.get('sample')==='1'){samplePrevious=clone(state);state={profile:demoProfile(),completed:[],created:true,remember:false,sample:true};}
if(['en','es'].includes(demoParams.get('lang')))lang=demoParams.get('lang');
view=['home','household','plan','practice','guide'].includes(location.hash.slice(1))?location.hash.slice(1):'home';
render();
if(state.sample&&demoParams.get('modal')==='compare')compare();
if(state.sample&&demoParams.get('modal')==='privacy')settings();
if(state.sample&&demoParams.get('modal')==='print')printPlan();
